import { createTRPCClient } from "@trpc/client";
import { getSession, GetSessionParams, useSession } from "next-auth/react";
import { useMemo } from "react";
import { AppRouter } from "./server";

export const getServerClient = async (ctx: GetSessionParams) => {
  const session = await getSession(ctx);

  return createTRPCClient<AppRouter>({
    url: "http://localhost:3000/api/trpc",
    headers: {
      "x-trpc-username": String(session?.username ?? ""),
    },
  });
};

export const useClient = () => {
  const session = useSession();

  return useMemo(
    () =>
      createTRPCClient<AppRouter>({
        url: "http://localhost:3000/api/trpc",
        headers: {
          "x-trpc-username": String(session?.data?.username ?? ""),
        },
      }),
    [session.data?.username],
  );
};

import * as trpc from "@trpc/server";
import { z } from "zod";
import { prismaClient } from "./prisma";

export const appRouter = trpc
  .router<AppContext>()
  .query("getLoggedInUser", {
    async resolve(req) {
      const user = await prismaClient.user.findUnique({
        where: {
          username: req.ctx.username,
        },
      });

      return user;
    },
  })
  .mutation("markUserAsCompletedOnboarding", {
    input: z.object({
      contactPreference: z.union([z.literal("email"), z.literal("phone")]),
    }),
    async resolve(req) {
      const user = await prismaClient.user.update({
        where: {
          username: req.ctx.username,
        },
        data: {
          hasCompletedOnboarding: true,
          contactPreference: req.input.contactPreference,
        },
      });

      return user;
    },
  });

export type AppRouter = typeof appRouter;

export interface AppContext {
  username: string;
}

